<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';
$error=null;$m=[];$prev=[];$targets=[];$signals=[];$trends=[];$topProducts=[];$user=[];$p=bi_step22_period($_GET['month']??null);
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.view');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];$m=bi_step22_metrics($pdo,$orgId,$p['start'],$p['end']);$prev=bi_step22_metrics($pdo,$orgId,$p['prev_start'],$p['prev_end']);$targets=bi_step22_targets($pdo,$orgId,$p['start'],$p['end'],$m);$signals=bi_step22_signals($pdo,$orgId,$m);$trends=bi_step22_monthly_trends($pdo,$orgId,6);$topProducts=bi_step22_top_products($pdo,$orgId,$p['start'],$p['end'],6);}catch(Throwable $e){$error=$e->getMessage();}
