$maxRevenue=1;foreach($trends as $t)$maxRevenue=max($maxRevenue,(float)$t['sales_revenue']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Executive BI - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • Executive BI</small></span></a><div class="os-top-actions"><a class="os-btn" href="bi_action_center.php">Action Center</a><a class="os-btn" href="bi_targets.php">Targets</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Executive BI</div><nav class="os-nav"><a class="active" href="executive_bi.php"><i class="dot"></i>Executive Overview</a><a href="bi_trends.php"><i class="dot"></i>Trends</a><a href="bi_funnel.php"><i class="dot"></i>Lead Funnel</a><a href="bi_profitability.php"><i class="dot"></i>Profitability</a><a href="bi_exposure.php"><i class="dot"></i>Exposure</a><a href="bi_action_center.php"><i class="dot"></i>Action Center</a><a href="bi_targets.php"><i class="dot"></i>Targets</a><a href="bi_export.php"><i class="dot"></i>Export</a><a href="step22_audit.php"><i class="dot"></i>STEP 22 Audit</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">EXECUTIVE BI • <?=bi_step22_h($p['label'])?></div><h1>One management view across Sales, Finance, CRM, Inventory, Purchases and Communications.</h1><p>Period KPIs are separated from current exposure. Verified profit uses only complete explicit cost coverage; unknown cost is never estimated.</p><div class="os-status-row"><span class="os-chip <?=!$error?'good':''?>"><?=$error?'Review required':'LIVE SOURCE KPIs'?></span><span class="os-chip">PROFIT: VERIFIED ONLY</span><span class="os-chip">EXPOSURE: CURRENT</span></div></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php else:?><section class="os-card" style="margin-top:14px"><form method="get" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap"><div><label class="bi-muted">Reporting month</label><input type="month" name="month" value="<?=bi_step22_h($p['key'])?>" style="display:block;padding:9px;border:1px solid #d8dfda;border-radius:10px"></div><button class="os-btn">Apply</button><span class="bi-muted">Previous comparison: <?=bi_step22_h(date('F Y',strtotime($p['prev_start'])))?></span></form></section><section class="bi-kpis"><div class="bi-kpi"><small>Sales Revenue</small><strong><?=bi_step22_money($m['sales_revenue'])?></strong><span><?=bi_step22_h(bi22chg($m,$prev,'sales_revenue'))?></span></div><div class="bi-kpi"><small>Verified Profit</small><strong><?=bi_step22_money($m['verified_profit'])?></strong><span><?=$m['profit_complete_sales']?> cost-covered • <?=$m['profit_deferred_sales']?> deferred</span></div><div class="bi-kpi"><small>Collections</small><strong><?=bi_step22_money($m['collections'])?></strong><span><?=bi_step22_h(bi22chg($m,$prev,'collections'))?></span></div><div class="bi-kpi"><small>New Leads</small><strong><?=$m['new_leads']?></strong><span><?=bi_step22_h(bi22chg($m,$prev,'new_leads'))?></span></div><div class="bi-kpi"><small>Lead Conversions</small><strong><?=$m['lead_conversions']?></strong><span><?=$m['conversion_rate']===null?'N/A':number_format((float)$m['conversion_rate'],1).'% of new leads'?></span></div></section><section class="bi-grid"><article class="os-card bi-span-8"><div class="os-title-row"><div><h2>6-Month Revenue Trend</h2><p>Active Product Sales only.</p></div><a class="os-btn" href="bi_trends.php">Full Trends</a></div><div class="bi-bars"><?php foreach($trends as $t):$w=min(100,max(0,(float)$t['sales_revenue']/$maxRevenue*100));?><div class="bi-bar-row"><span><?=bi_step22_h($t['label'])?></span><div class="bi-bar-track"><div class="bi-bar-fill" style="width:<?=$w?>%"></div></div><strong><?=bi_step22_money($t['sales_revenue'])?></strong></div><?php endforeach;?></div></article><article class="os-card bi-span-4"><div class="os-title-row"><div><h2>Current Exposure</h2><p>Live balances, not monthly totals.</p></div></div><div class="bi-note"><b>Customer Receivable</b><strong style="float:right"><?=bi_step22_money($m['customer_receivable'])?></strong></div><div class="bi-note"><b>Supplier Payable</b><strong style="float:right"><?=bi_step22_money($m['supplier_payable'])?></strong></div><div class="bi-note"><b>Sellable Inventory Units</b><strong style="float:right"><?=bi_step22_num($m['inventory_units'],3)?></strong></div><div class="bi-note"><b>Known Inventory Value</b><strong style="float:right"><?=bi_step22_money($m['inventory_value_known'])?></strong><small class="bi-muted">Cost coverage <?=$m['inventory_cost_coverage']===null?'N/A':number_format((float)$m['inventory_cost_coverage'],1).'%'?></small></div></article><article class="os-card bi-span-6"><div class="os-title-row"><div><h2>Targets vs Actual</h2><p>Only explicitly configured targets appear.</p></div><a class="os-btn" href="bi_targets.php">Manage</a></div><?php if(!$targets):?><div class="bi-note"><b>No targets configured for this period.</b><small class="bi-muted">This is valid; STEP 22 does not invent management targets.</small></div><?php endif;?><?php foreach(array_slice($targets,0,6) as $t):$pct=$t['achievement_pct']===null?0:min(100,max(0,(float)$t['achievement_pct']));?><div class="bi-target"><div class="bi-target-head"><div><b><?=bi_step22_h($t['target_name'])?></b><small class="bi-muted">Actual <?=is_numeric($t['actual_value'])?bi_step22_num($t['actual_value'],2):'N/A'?> / Target <?=bi_step22_num($t['target_value'],2)?></small></div><strong class="<?=$t['met']===true?'bi-good':($t['met']===false?'bi-warn':'')?>"><?=$t['achievement_pct']===null?'N/A':number_format((float)$t['achievement_pct'],1).'%'?></strong></div><div class="bi-progress"><span style="width:<?=$pct?>%"></span></div></div><?php endforeach;?></article><article class="os-card bi-span-6"><div class="os-title-row"><div><h2>Action Signals</h2><p>Fact-based conditions only.</p></div><a class="os-btn" href="bi_action_center.php">Open Center</a></div><?php if(!$signals):?><div class="bi-note"><b>No current action signal.</b></div><?php endif;?><?php foreach(array_slice($signals,0,6) as $s):?><div class="bi-signal <?=bi_step22_h($s['severity'])?>"><div><b><?=bi_step22_h($s['title'])?></b><small><?=bi_step22_h($s['detail'])?></small></div><span class="bi-pill"><?=bi_step22_h(strtoupper($s['workflow_status']))?></span></div><?php endforeach;?></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Top Products • <?=bi_step22_h($p['label'])?></h2><p>Ranked by active Product Sale revenue.</p></div><a class="os-btn" href="bi_profitability.php?month=<?=rawurlencode($p['key'])?>">Profitability</a></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Stock No.</th><th>Product</th><th>Qty</th><th>Revenue</th><th>VP</th><th>Verified Profit</th><th>Cost Coverage</th></tr></thead><tbody><?php if(!$topProducts):?><tr><td colspan="7">No Product Sales in this period.</td></tr><?php endif;?><?php foreach($topProducts as $r):?><tr><td><?=bi_step22_h($r['stock_no'])?></td><td><?=bi_step22_h($r['product_name_snapshot'])?></td><td><?=bi_step22_num($r['qty'],3)?></td><td><?=bi_step22_money($r['revenue'])?></td><td><?=bi_step22_num($r['vp'],3)?></td><td><?=bi_step22_money($r['verified_profit'])?></td><td><?=$r['costed_lines']?> / <?=$r['lines']?> lines</td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>BI truth boundary:</strong> revenue, VP, cash, receivable/payable and operational counts come from their authoritative modules. Profit and inventory value remain partial/deferred where actual cost evidence is incomplete.</div></main></div></body></html>